const icon = (name, cls='') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.model}</svg>`;
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => Number(n||0).toLocaleString();
const shortDate = d => d ? new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'}) : '—';
const bytes = n => n<1024 ? `${n} B` : n<1048576 ? `${(n/1024).toFixed(1)} KB` : n<1073741824 ? `${(n/1048576).toFixed(1)} MB` : `${(n/1073741824).toFixed(2)} GB`;
const methods = {tuna:{name:'Tuna',icon:'fish',caption:'Teach a consistent identity.',description:'Train 4-bit adapters on examples conditioned by your saved system policy.',foot:'Policy-conditioned QLoRA',tag:'Policy + QLoRA'},qlora:{name:'QLoRA',icon:'bolt',caption:'4-bit adapter training.',description:'Train lightweight adapters on a frozen 4-bit base model to reduce GPU memory use.',foot:'4-bit NF4 · Double quantization',tag:'Efficient'},lora:{name:'LoRA',icon:'sliders',caption:'Keep it simple.',description:'Adapt a small set of parameters while keeping the base model weights frozen.',foot:'Full-precision base · Low-rank adapters',tag:'Classic'}};
const models=[{name:'Qwen3 · 0.6B',id:'Qwen/Qwen3-0.6B',family:'Qwen',size:'0.6B',description:'A compact starting point for small GPU experiments.'},{name:'Qwen3 · 1.7B',id:'Qwen/Qwen3-1.7B',family:'Qwen',size:'1.7B',description:'More capacity for domain-specific assistants on smaller GPUs.'},{name:'Llama 3.2 · 1B',id:'meta-llama/Llama-3.2-1B-Instruct',family:'Llama',size:'1B',description:'A small instruction model. Access and license may be required.'},{name:'SmolLM2 · 360M',id:'HuggingFaceTB/SmolLM2-360M-Instruct',family:'SmolLM',size:'360M',description:'A lightweight model for quick iteration and learning.'}];
let state={page:location.hash.slice(1)||'overview',status:null,datasets:[],runs:[],connected:false,search:'',filter:'all',settings:{offline:false},baseline:null};
let modalType=null,modalData=null,wizard=null,activeRun=null,refreshing=false,lastFocus=null,modalEpoch=0,runRequest=0,modalLookup=0,fileRequest=0,trainingPending=false,datasetPending=false,settingsPending=false;
const pendingActions=new Set();
const isRecord=value=>!!value&&typeof value==='object'&&!Array.isArray(value);
function readStored(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')??fallback;}catch{return fallback;}}
function saveStored(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Browser storage is full or unavailable. This setting will last until the page closes.');return false;}}
const storedSettings=readStored('tuna-settings',{});
if(isRecord(storedSettings)&&typeof storedSettings.offline==='boolean')state.settings.offline=storedSettings.offline;
const storedBaseline=readStored('tuna-baseline',null);
if(isRecord(storedBaseline))state.baseline=storedBaseline;
const api=async(path,options={})=>{
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),options.method&&options.method!=='GET'?120000:25000);
 let response,text;
 try{
  try{response=await fetch('/api'+path,{...options,signal:options.signal||controller.signal,headers:{'Content-Type':'application/json',...(options.headers||{})}});text=await response.text();}
  catch(cause){const timedOut=controller.signal.aborted;const error=new Error(timedOut?'The local engine took too long to respond. Check its terminal and refresh before trying again.':'Could not reach the local engine. Check that Tuna Studio is running, then try again.');error.kind=timedOut?'timeout':'network';throw error;}
  let data;
  try{data=text?JSON.parse(text):{};}catch{const error=new Error(response.ok?'The local engine returned an unreadable response. Refresh and try again.':`The local engine could not complete this request (${response.status}). Check its terminal for details.`);error.status=response.status;error.kind='response';throw error;}
  if(!response.ok){const error=new Error(typeof data?.error==='string'?data.error:`Request failed (${response.status}).`);error.status=response.status;error.kind='response';throw error;}
  if(!isRecord(data)){const error=new Error('The local engine returned an unexpected response. Refresh and try again.');error.kind='response';throw error;}
  return data;
 }finally{clearTimeout(timeout);}
};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function btn(text,action,kind='',ico=''){return `<button class="button ${kind}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;}
function pill(text,green=false){return `<span class="pill ${green?'green':''}">${green?'<i class="dot"></i>':''}${esc(text)}</span>`;}
function statusBadge(status){status=typeof status==='string'?status:'queued';return `<span class="status ${esc(status)}">${['running','completed'].includes(status)?'<i class="dot"></i>':''}${esc(status.replace(/_/g,' '))}</span>`;}
function empty(title,description,action='',label='',ico='runs'){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${description}</p>${action?btn(label,action,'','plus'):''}</div>`;}
function head(title,description,action='new-run',label='New training run',ico='plus'){return `<div class="page-head"><div><div class="eyebrow">YOUR LOCAL AI WORKSPACE</div><h1>${title}</h1><p>${description}</p></div>${action?btn(label,action,'primary',ico):''}</div>`;}
function recipeCards(){return `<div class="recipes">${Object.entries(methods).map(([key,m])=>`<article class="recipe ${key==='tuna'?'featured':''}"><div class="recipe-heading"><div class="recipe-icon">${icon(m.icon)}</div><h3>${m.name}</h3><span class="tag">${m.tag}</span></div><p>${m.description}</p><div class="recipe-foot"><span>${m.foot}</span><button aria-label="Create ${m.name} run" data-action="recipe" data-method="${key}">${icon('arrow')}</button></div></article>`).join('')}</div>`;}
function gpuCard(){const d=state.status?.device||{};const total=Number(d.vram_total_gb||0),used=Number(d.vram_used_gb||0);return `<div class="panel"><div class="panel-header"><h2>Your local engine</h2>${pill(state.status?.checking?'Checking':d.cuda?'CUDA ready':'Setup needed',!!d.cuda)}</div><div class="panel-body"><div class="gpu-title"><div class="gpu-icon">${icon('cpu')}</div><div><h3>${esc(d.name||'Detecting your hardware…')}</h3><p>${total?`${total.toFixed(1)} GB dedicated memory`:'Local hardware detection'}</p></div></div><div class="memory-label"><span>GPU memory</span><strong>${total?`${used.toFixed(1)} / ${total.toFixed(1)} GB`:'—'}</strong></div><div class="progress"><span style="width:${Math.min(100,total?used/total*100:0)}%"></span></div><div class="gpu-details"><div>Compute<strong>${d.cuda?'CUDA':'CPU runtime'}</strong></div><div>Model access<strong>${state.settings.offline?'Offline':'Downloads enabled'}</strong></div><div>Storage<strong>On device</strong></div></div>${!d.cuda?`<button class="button ghost small" data-nav="settings" style="margin-top:15px;font-size:9px">Set up the training engine ${icon('arrow')}</button>`:''}</div></div>`;}
function runTable(runs,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Run name</th><th>Method</th><th>Status</th>${!compact?'<th>Dataset</th><th>Created</th>':''}<th>Loss</th></tr></thead><tbody>${runs.map(r=>`<tr class="clickable" data-action="run" data-id="${esc(r.id)}" tabindex="0" role="button" aria-label="Open ${esc(r.name||r.config?.name||'run')}"><td><strong>${esc(r.name||r.config?.name||'Untitled run')}</strong><div class="small muted" style="font-size:9px;margin-top:4px">${esc((r.model||r.config?.model||'').split(/[\\/]/).pop())}</div></td><td>${methods[r.method||r.config?.method]?.name||'LoRA'}</td><td>${statusBadge(r.status)}</td>${!compact?`<td>${esc(state.datasets.find(d=>d.id===(r.dataset_id||r.config?.dataset_id))?.name||'Local dataset')}</td><td>${shortDate(r.created_at)}</td>`:''}<td>${latestLoss(r)}</td></tr>`).join('')}</tbody></table></div>`;}
function logMessage(l){const message=typeof l==='string'?l:l?.message||JSON.stringify(l);try{const data=JSON.parse(message);if(data?.type==='complete')return 'Training complete. Adapter weights and run metadata saved locally.';}catch{}return message;}
function metricsOf(r){return Array.isArray(r.metrics)?r.metrics.filter(isRecord):[];}
function lastMetric(r){return metricsOf(r).at(-1)||r.latest_metric||r.summary||{};}
function latestLoss(r){const loss=metricsOf(r).filter(m=>typeof m.loss==='number').at(-1)?.loss??r.latest_metric?.loss??r.summary?.loss;return typeof loss==='number'?loss.toFixed(4):'—';}
function overview(){
 const d=state.status?.device||{};
 return `${head('Workspace','Train, evaluate in chat, and export local models.')}
 <div class="stats"><div class="stat"><div class="stat-label">Available GPU memory ${icon('cpu')}</div><div class="stat-value">${d.vram_total_gb?Math.max(0,d.vram_total_gb-(d.vram_used_gb||0)).toFixed(1):'—'}<small>GB</small></div><div class="stat-caption">${d.vram_total_gb?`${d.vram_total_gb.toFixed(1)} GB total on your device`:'Waiting for the local engine'}</div></div><div class="stat"><div class="stat-label">Training runs ${icon('runs')}</div><div class="stat-value">${fmt(state.runs.length)}<small>runs</small></div><div class="stat-caption">${state.runs.filter(r=>['running','starting','queued'].includes(r.status)).length} active · ${state.runs.filter(r=>r.status==='completed').length} completed</div></div><div class="stat"><div class="stat-label">Datasets ${icon('data')}</div><div class="stat-value">${fmt(state.datasets.length)}<small>datasets</small></div><div class="stat-caption">${fmt(state.datasets.reduce((a,d)=>a+d.rows,0))} training examples</div></div><div class="stat"><div class="stat-label">Quantized adapter training ${icon('bolt')}</div><div class="stat-value">4<small>bit base weights</small></div><div class="stat-caption">NF4 quantization with Tuna and QLoRA</div></div></div>
 <div class="bottom-grid"><div class="panel"><div class="panel-header"><h2>Recent training runs</h2><button class="button ghost" data-nav="runs">View all ${icon('arrow')}</button></div>${state.runs.length?runTable(state.runs.slice(0,4),true):empty('No training runs yet','Import a dataset and choose a base model to start.','new-run','Create training run')}</div>${gpuCard()}</div>
 <div class="section-head"><div><h2>Training methods</h2><p>Policy conditioning, quantized adapters, or full-precision adapters.</p></div><button class="button ghost" data-nav="methods">Compare methods ${icon('arrow')}</button></div>${recipeCards()}
 ${!state.runs.length?`<section class="welcome"><div><div class="eyebrow">LOCAL WORKFLOW</div><h2>From dataset to tuned weights.</h2><p>Import JSONL examples, train an adapter, test the result in chat, and export a standalone GGUF.</p>${btn('Create training run','new-run','dark','arrow')}</div><div class="workflow"><div class="workflow-step"><div class="workflow-square">${icon('data')}</div><span>Import data</span></div><div class="flow-line"></div><div class="workflow-step"><div class="workflow-square">${icon('fish')}</div><span>Train locally</span></div><div class="flow-line"></div><div class="workflow-step"><div class="workflow-square">${icon('model')}</div><span>Chat & export</span></div></div></section>`:''}`;
}
function runsPage(){const filtered=state.runs.filter(r=>(state.filter==='all'||r.status===state.filter)&&JSON.stringify([r.name,r.model,r.config]).toLowerCase().includes(state.search.toLowerCase()));return `${head('Training runs','Track training progress, inspect results, and open completed models in chat.')}<div class="toolbar"><div class="search">${icon('search')}<input id="run-search" placeholder="Find a training run…" value="${esc(state.search)}" aria-label="Search training runs"></div><div class="filters">${['all','running','completed','failed'].map(s=>`<button class="filter ${state.filter===s?'active':''}" data-action="filter" data-value="${s}">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</div></div><div class="panel">${filtered.length?runTable(filtered):empty(state.runs.length?'No matching runs':'No training runs yet',state.runs.length?'Try a different search or status.':'Choose your method, add your examples, and start a local training run.','new-run','New training run')}</div>`;}
function datasetsPage(){return `${head('Datasets','Import, validate, and manage local JSONL training examples.','import','Import dataset','upload')}<div class="callout">${icon('shield')}<div>Private from the first example. Datasets are validated and saved on this machine. Supports chat <strong>messages</strong> and <strong>prompt / completion</strong> JSONL.</div></div>${state.datasets.length?`<div class="dataset-grid">${state.datasets.map(d=>`<article class="dataset-card"><div class="recipe-icon">${icon('data')}</div><h3>${esc(d.name)}</h3><p>${fmt(d.rows)} validated training examples</p><div class="card-meta"><span>${bytes(d.size_bytes||0)}</span><span>Added ${shortDate(d.created_at)}</span></div><div class="card-bottom"><button class="button ghost" data-action="dataset" data-id="${d.id}">Preview examples ${icon('arrow')}</button><button class="icon-btn" aria-label="Delete ${esc(d.name)}" data-action="delete-dataset" data-id="${d.id}">${icon('trash')}</button></div></article>`).join('')}</div>`:`<div class="panel">${empty('No datasets imported','Drop in your own JSONL file, or use our small example dataset to explore the workflow.','import','Import your first dataset','data')}<div style="text-align:center;padding:0 20px 30px">${btn('Try a sample dataset','sample','ghost','file')}</div></div>`}`;}
function modelsPage(){return `${head('Model library','Use a local GGUF, model directory, or Hugging Face model ID.','custom-model','Use a local model','folder')}<div class="callout">${icon('info')}<div>Model files download from Hugging Face when you start a run with downloads enabled. They are cached for reuse. Your datasets and training stay on your machine.</div></div><div class="model-grid">${models.map((m,i)=>`<article class="model-card"><div style="display:flex;justify-content:space-between"><div class="recipe-icon">${icon('model')}</div>${pill(m.size)}</div><h3>${m.name}</h3><p>${m.description}</p><div class="card-meta"><span>${m.family}</span><span>Downloaded once, then cached</span></div><div class="card-bottom"><span class="small muted" style="font-size:9px">Hugging Face compatible</span><button class="button ghost" data-action="choose-model" data-index="${i}">Use model ${icon('arrow')}</button></div></article>`).join('')}</div>`;}
function methodsPage(){return `${head('Training methods','Choose an approach for your dataset, model, and hardware.','new-run','New training run')}${recipeCards()}<div class="methods-detail"><div class="panel"><div class="panel-header"><h2>${icon('fish')} How Tuna works</h2>${pill('Policy-conditioned QLoRA',true)}</div><div class="panel-body"><p>Tuna combines QLoRA with a canonical system policy. It trains on your identity and instructions, then packages them with the adapter for consistent inference.</p><ol class="steps-list"><li><strong>Write your model’s identity</strong>Define the behavior you want in a system prompt.</li><li><strong>Train it into the examples</strong>Tuna replaces system messages with your canonical policy for every training conversation.</li><li><strong>Keep the policy at inference</strong>The included wrapper rejects caller-provided system messages and inserts the saved policy.</li></ol><div class="callout warning" style="margin-bottom:0">${icon('info')}Training improves adherence; it cannot make instructions mathematically unoverrideable. Wrapper enforcement applies only while that wrapper is used.</div></div></div><div class="panel"><div class="panel-header"><h2>Memory and training defaults</h2>${icon('leaf')}</div><div class="panel-body"><ol class="steps-list"><li><strong>4-bit NF4 + double quantization</strong>Reduce frozen base-weight memory in QLoRA and Tuna.</li><li><strong>Gradient checkpointing</strong>Trade recomputation for lower activation memory.</li><li><strong>Dynamic padding + SDPA</strong>Pad each batch only as needed and use PyTorch attention kernels.</li><li><strong>Measure, then compare</strong>Track loss, training time, throughput, and peak allocated VRAM from actual runs.</li></ol><button class="button ghost" data-nav="benchmarks">Open benchmarks ${icon('arrow')}</button></div></div></div>`;}
function benchmarkPage(){const completed=state.runs.filter(r=>r.status==='completed');return `${head('Benchmarks','Compare measured training time, memory use, and throughput.','export-benchmarks','Export results','download')}<div class="callout">${icon('chart')}<div>For a meaningful framework comparison, use identical training conditions. Compare the same model, data, GPU, sequence length, batch size, and training steps.</div></div><div class="panel"><div class="panel-header"><h2>Measured local runs</h2>${pill(`${completed.length} completed`)}</div>${completed.length?`<div class="table-wrap"><table><thead><tr><th>Run</th><th>Method</th><th>Peak VRAM</th><th>Train time</th><th>Tokens / sec</th><th>Loss</th></tr></thead><tbody>${completed.map(r=>{const m={...lastMetric(r),...r.summary};return `<tr class="clickable" data-action="run" data-id="${r.id}"><td><strong>${esc(r.name||r.config?.name)}</strong></td><td>${methods[r.method||r.config?.method]?.name||'—'}</td><td>${metricNum(m.peak_vram_gb??m.peak_memory_gb??(typeof m.peak_vram_mb==='number'?m.peak_vram_mb/1024:undefined),' GB')}</td><td>${metricNum(m.elapsed_seconds??m.train_seconds,' s')}</td><td>${metricNum(m.tokens_per_second)}</td><td>${latestLoss(r)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No completed runs yet','Complete a training run to see measured memory use, throughput, and loss here.','new-run','Start an experiment','chart')}</div><div class="methods-detail"><div class="panel"><div class="panel-header"><h2>External baseline</h2><span class="baseline">User-supplied</span></div><div class="panel-body"><p class="small muted">Bring a baseline from Unsloth or another trainer. It stays labeled as imported, separate from locally measured results.</p>${state.baseline?`<div class="code" style="margin-top:15px">${esc(JSON.stringify(state.baseline,null,2))}</div>`:''}<div style="margin-top:15px">${btn(state.baseline?'Replace baseline':'Import baseline JSON','baseline','','upload')}</div></div></div><div class="panel"><div class="panel-header"><h2>A comparison worth trusting</h2>${icon('check')}</div><div class="panel-body"><p class="small muted">Use identical model and dataset revisions, random seed, precision, optimizer, effective batch size, and target steps. Include warm-up, synchronize CUDA, and report loss alongside speed. A faster run is useful only if it still learns.</p><button class="button ghost" data-nav="docs" style="margin-top:15px">Read the benchmark notes ${icon('arrow')}</button></div></div></div>`;}
function metricNum(n,suffix=''){return typeof n==='number'&&Number.isFinite(n)?`${n.toFixed(2)}${suffix}`:'—';}
function settingsPage(){const s=state.status||{},deps=s.dependencies||{};return `${head('Settings','Model access, runtime dependencies, and GPU status.','','')}<div class="settings-form"><div class="panel"><div class="panel-header"><h2>Privacy & model access</h2>${icon('shield')}</div><div class="panel-body"><div class="toggle-row" style="padding-top:0"><div><strong>Download missing models</strong><p>Fetch model and tokenizer files from Hugging Face when needed. Datasets and training stay local.</p></div><input type="checkbox" class="toggle" id="model-download-toggle" aria-label="Download missing models" ${!state.settings.offline?'checked':''}></div><div class="toggle-row"><div><strong>Anonymous analytics</strong><p>None. There is no telemetry in Tuna Studio.</p></div><span class="pill green">Never collected</span></div><p class="small muted" style="margin-top:18px">Settings are stored in this browser. Runs, datasets, and adapters are stored in the app’s local <span class="mono">data/</span> directory.</p></div></div><div class="panel" style="margin-top:22px"><div class="panel-header"><h2>Training engine</h2>${btn('Refresh','refresh','','refresh')}</div><div class="panel-body"><div class="gpu-title"><div class="gpu-icon">${icon('cpu')}</div><div><h3>${esc(s.device?.name||'Detecting hardware')}</h3><p>${s.device?.cuda?'CUDA runtime available':'CUDA runtime unavailable'} · ${s.version?`Tuna Studio ${esc(s.version)}`:'Local engine'}</p></div></div>${Object.entries(deps).map(([name,ok])=>`<div class="toggle-row"><strong class="mono">${esc(name)}</strong>${pill(ok?'Installed':'Missing',!!ok)}</div>`).join('')}${s.methods_ready?.qlora?`<div class="callout" style="margin-top:20px;margin-bottom:0">${icon('check')}The engine is ready. Choose a model and dataset to begin.</div>`:`<div class="callout warning" style="margin-top:20px;margin-bottom:12px">${icon('info')}<div>${s.checking?'Checking your training runtime…':esc([...(s.missing||[]),...(s.setup_actions||[])].join(' · ')||'A compatible CUDA-enabled PyTorch installation is required for GPU training.')}</div></div><p class="small muted">LoRA can run on CPU when its dependencies are installed. Your GPU is detected independently of PyTorch. A CPU-only PyTorch build cannot use it for QLoRA. See the setup guide for a matching CUDA build.</p>`}<button class="button ghost" data-nav="docs" style="margin-top:14px">Open setup guide ${icon('arrow')}</button></div></div></div>`;}
function docsPage(){return `${head('Quick-start guide','Set up the runtime and complete your first training run.','','')}<div class="panel"><div class="panel-body docs-copy"><h2 style="margin-top:0">1. Get the engine ready</h2><p>The interface runs with Python’s standard library. Real training also requires PyTorch, Transformers, PEFT, Accelerate, and bitsandbytes. Install a CUDA-enabled PyTorch build compatible with your NVIDIA GPU using the <a href="https://pytorch.org/get-started/locally/" target="_blank" rel="noopener">official PyTorch selector ↗</a>, then install <code>requirements-train.txt</code> in a dedicated environment.</p><div class="code">python -m venv .venv\n.venv\\Scripts\\activate\n# Install CUDA-enabled PyTorch using the official selector\npip install -r requirements-train.txt\npython server.py</div><h2>2. Bring a model and examples</h2><p>Use a local Llama-family .gguf file, a Hugging Face model directory, or a model ID. GGUF files are imported locally into training weights first; extra disk space is required. Enable Download missing models to fetch files into the local cache before training. Switch it off to use cached files only. Gated models require access configured locally.</p><p>Each JSONL line is one conversation. Include a user message and a non-empty assistant response. The assistant responses teach the behavior you want.</p><div class="code">${esc(JSON.stringify({messages:[{role:'user',content:'What do you do?'},{role:'assistant',content:'I help you write clear, friendly product documentation.'}]}))}</div><h2>3. Choose how to train</h2><p><strong>QLoRA</strong> uses a quantized frozen base with trainable adapters. <strong>LoRA</strong> uses a full-precision frozen base. <strong>Tuna</strong> adds your canonical system policy to the QLoRA training data and saves it with a policy-aware inference wrapper.</p><div class="callout warning">${icon('info')}A policy inside training examples is not an unbreakable constraint inside model weights. Adversarial inputs can still cause policy violations. The wrapper prevents callers replacing the system message; it cannot guarantee every generated response.</div><h2>4. Read the learning signals</h2><p>Watch the actual loss curve, peak allocated CUDA memory, elapsed training time, and token throughput. For meaningful comparisons with Unsloth, match hardware, model, dataset, context length, optimizer, effective batch size, seed, and steps. Compare validation quality separately before claiming an improvement.</p><h2>5. Keep what you make</h2><p>Completed runs export a local ZIP containing adapter weights and associated training files. Adapter ZIPs use a separate base model. Choose Save as GGUF in a completed run to merge the trained adapter into a standalone Q8_0 or F16 GGUF file. Tuna also saves a policy manifest and a wrapper that re-injects the policy at inference. See <code>docs/TRAINING.md</code> in your app folder for details.</p><div style="margin-top:22px;display:flex;gap:10px">${btn('Create a training run','new-run','primary','plus')}${btn('Download sample JSONL','download-sample','','download')}</div></div></div>`;}
function render(){const names={overview:'Overview',chat:'Chat',runs:'Training runs',datasets:'Datasets',models:'Model library',methods:'Fine-tuning methods',benchmarks:'Benchmarks',settings:'Settings',docs:'Quick-start guide'};if(!names[state.page])state.page='overview';const nav=[['overview','grid','Overview'],['chat','chat','Chat'],['runs','runs','Training runs'],['datasets','data','Datasets'],['models','model','Model library'],['methods','sliders','Methods'],['benchmarks','chart','Benchmarks']];document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#overview" class="brand" aria-label="Tuna Studio home"><img class="brand-icon" src="assets/tuna-mark.png" alt="Tuna Studio"><div class="brand-text">tuna<span style="color:#75a389">.</span><small>STUDIO</small></div></a><div class="workspace"><div class="workspace-icon">${icon('folder')}</div><div><p>Personal workspace</p><span class="muted">Local machine</span></div></div><div class="section-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([key,ico,name])=>`<button data-nav="${key}" class="${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''}>${icon(ico)}<span>${name}</span>${key==='runs'&&state.runs.length?`<span class="nav-count">${state.runs.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-spacer"></div><nav class="nav" aria-label="Help and settings"><button data-nav="docs" class="${state.page==='docs'?'active':''}">${icon('book')}Quick-start guide</button><button data-nav="settings" class="${state.page==='settings'?'active':''}">${icon('settings')}Settings</button></nav><div class="local-note"><strong>${icon('shield')}Local workspace</strong><p>Runs and datasets stay on this machine.<br>No telemetry.</p></div><div class="profile"><div class="avatar">Y</div><div><p>Your workspace</p><small>On-device training</small></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span class="muted">Workspace</span>${icon('chevron')}<span>${names[state.page]}</span></div><div class="top-actions"><span class="muted">${icon('lock')} &nbsp; Local workspace</span>${pill(state.connected?'Local engine connected':'Engine unavailable',state.connected)}<button class="icon-btn" data-nav="docs" aria-label="Help">${icon('info')}</button></div></header>${!state.connected?'<div class="connection-banner">The local engine is unavailable. Check that Tuna Studio is running. Reconnecting automatically…</div>':''}<div class="content">${({overview,chat:chatPage,runs:runsPage,datasets:datasetsPage,models:modelsPage,methods:methodsPage,benchmarks:benchmarkPage,settings:settingsPage,docs:docsPage}[state.page])()}<footer class="footer"><span>${icon('leaf')} Local training · No telemetry</span><span>Tuna Studio <span class="mono">v0.1</span> &nbsp; · &nbsp; All data stays local</span></footer></div></main></div>`;if(state.page==='chat')chatMount();}
function navigate(page){state.page=page;state.search='';state.filter='all';location.hash=page;render();window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'overview';render();});
function normalizeStatus(value){
 const status={...value},device=isRecord(value.device)?{...value.device}:{};
 for(const key of ['vram_total_gb','vram_used_gb'])device[key]=Number.isFinite(Number(device[key]))?Math.max(0,Number(device[key])):0;
 status.device=device;
 for(const key of ['missing','setup_actions'])status[key]=Array.isArray(status[key])?status[key]:[];
 return status;
}
function normalizeRuns(runs){return runs.filter(r=>isRecord(r)&&typeof r.id==='string').map(r=>{const config=isRecord(r.config)?{...r.config}:{};for(const key of ['name','model'])if(typeof config[key]!=='string')config[key]='';return {...r,name:typeof r.name==='string'?r.name:'',model:typeof r.model==='string'?r.model:'',config,summary:isRecord(r.summary)?r.summary:{},metrics:metricsOf(r)};}).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));}
function connectionChrome(){
 const indicator=document.querySelector('.top-actions .pill');if(indicator)indicator.outerHTML=pill(state.connected?'Local engine connected':'Engine unavailable',state.connected);
 const banner=document.querySelector('.connection-banner');if(state.connected){banner?.remove();return;}
 if(!banner){const main=document.querySelector('.main'),content=document.querySelector('.content');if(main&&content){const notice=document.createElement('div');notice.className='connection-banner';notice.textContent='The local engine is unavailable. Check that Tuna Studio is running. Reconnecting automatically…';main.insertBefore(notice,content);}}
}
async function refresh(initial=false){
 if(refreshing)return;refreshing=true;
 try{
  const [status,datasets,runs,preferences]=await Promise.allSettled([api('/status'),api('/datasets'),api('/runs'),api('/settings')]);
  state.connected=status.status==='fulfilled';
  if(state.connected)state.status=normalizeStatus(status.value);
  if(datasets.status==='fulfilled'&&Array.isArray(datasets.value.datasets))state.datasets=datasets.value.datasets.filter(d=>isRecord(d)&&typeof d.id==='string').map(d=>({...d,rows:Number.isFinite(Number(d.rows))?Math.max(0,Number(d.rows)):0}));
  if(runs.status==='fulfilled'&&Array.isArray(runs.value.runs))state.runs=normalizeRuns(runs.value.runs);
  if(preferences.status==='fulfilled'&&typeof preferences.value.settings?.offline==='boolean')state.settings.offline=preferences.value.settings.offline;
  const typing=document.activeElement?.matches('input,textarea,select');
  if(initial||(!modalType&&!typing&&state.page!=='chat'))render();else connectionChrome();
  if(modalType==='run'&&activeRun)await showRun(activeRun,true);
 }finally{refreshing=false;}
}
function openModal(title,description,body,footer='',wide=false,focus=true){modalEpoch++;if(!document.querySelector('.modal'))lastFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${description}</p></div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';if(focus)setTimeout(()=>document.querySelector('.modal input:not([type=file]), .modal textarea, .modal button')?.focus(),0);}
function closeModal(){modalEpoch++;runRequest++;fileRequest++;modalType=null;modalData=null;activeRun=null;document.querySelector('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus();}
function sampleContent(){return [{messages:[{role:'user',content:'What do you do?'},{role:'assistant',content:'I help turn complicated ideas into clear, friendly documentation.'}]},{messages:[{role:'user',content:'Explain a training epoch in one sentence.'},{role:'assistant',content:'An epoch is one complete pass through your training examples.'}]},{messages:[{role:'user',content:'What is an adapter?'},{role:'assistant',content:'An adapter is a small set of trainable weights that helps a base model learn a new task.'}]},{messages:[{role:'user',content:'How should I start a new project?'},{role:'assistant',content:'Start with one clear goal, a small set of good examples, and a baseline you can measure.'}]}].map(x=>JSON.stringify(x)).join('\n');}
function importModal(backToWizard=false){modalType='import';modalData={backToWizard};openModal('Import dataset','Import a local JSONL file or paste a few training conversations.',`<div id="import-error"></div><div class="field"><label for="dataset-name">Dataset name</label><input id="dataset-name" placeholder="My helpful assistant"></div><div class="upload-zone" id="drop-zone">${icon('upload')}<strong>Drop your .jsonl file here</strong><p>or click to browse · up to 25 MB per import request</p><input type="file" id="dataset-file" accept=".jsonl,.ndjson,.json" aria-label="Choose JSONL dataset"></div><div class="or">or paste your JSONL</div><div class="field"><textarea id="dataset-content" aria-label="JSONL examples" class="mono" rows="5" placeholder='${esc('{"messages":[{"role":"user","content":"Hello"},{"role":"assistant","content":"Hi there!"}]}')}'></textarea><small>One JSON object per line. Chat messages or prompt / completion pairs.</small></div>`,`${btn('Use sample','paste-sample','ghost','file')}<div>${btn('Cancel','close')}${btn('Validate & import','save-dataset','primary','check')}</div>`);}
async function loadFile(file){
 if(!file||modalType!=='import')return;
 if(file.size>25*1024*1024){toast('Please choose a file smaller than 25 MB.');return;}
 const request=++fileRequest,epoch=modalEpoch;
 try{const content=await file.text();if(request!==fileRequest||epoch!==modalEpoch||modalType!=='import')return;document.querySelector('#dataset-content').value=content;const name=document.querySelector('#dataset-name');if(!name.value)name.value=file.name.replace(/\.(jsonl|ndjson|json)$/i,'');toast(`${file.name} loaded. Ready to validate.`);}catch{if(epoch===modalEpoch)toast('This file could not be read. Try selecting it again or paste the JSONL text.');}
}
function datasetRequest(name,content){
 if(!content.trim())throw new Error('Choose a JSONL file or paste at least one training example.');
 if(name.length>160||/[\r\n\0/\\]/.test(name))throw new Error('Dataset name must be at most 160 characters, without line breaks or path separators.');
 const body=JSON.stringify({name:name||'Untitled dataset',content});
 if(new TextEncoder().encode(body).length>25*1024*1024)throw new Error('This import exceeds the 25 MB request limit. Split it into smaller JSONL files.');
 return body;
}
async function saveDataset(){
 if(datasetPending||modalType!=='import')return;
 const name=document.querySelector('#dataset-name').value.trim(),content=document.querySelector('#dataset-content').value,el=document.querySelector('[data-action=save-dataset]'),epoch=modalEpoch,back=modalData?.backToWizard,owner=wizard;
 datasetPending=true;el.disabled=true;
 try{
  const result=await api('/datasets',{method:'POST',body:datasetRequest(name,content)});await refresh();toast('Dataset validated and saved locally.');
  if(epoch!==modalEpoch||modalType!=='import')return;
  if(back&&wizard===owner&&wizard){wizard.dataset_id=(result.dataset||result).id;modalType='wizard';wizardView();}else{closeModal();navigate('datasets');}
 }catch(e){if(epoch===modalEpoch){const error=document.querySelector('#import-error');if(error)error.innerHTML=`<div class="callout error">${icon('info')}${esc(e.message)}</div>`;}else toast(e.message);}
 finally{datasetPending=false;if(el.isConnected)el.disabled=false;}
}
function newRun(method='qlora',model=''){if(!methods[method])method='qlora';wizard={step:1,name:'My first fine-tune',model:model||models[3].id,method,dataset_id:state.datasets[0]?.id||'',epochs:1,learning_rate:.0002,batch_size:1,gradient_accumulation:8,max_seq_length:1024,lora_rank:16,lora_alpha:32,gradient_checkpointing:true,system_prompt:'You are a clear, friendly assistant. Explain ideas simply, be honest about uncertainty, and stay focused on helping the user.',offline:!!state.settings.offline,seed:42};modalType='wizard';wizardView();}
function field(id,label,value,type='text',extra='',hint=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</div>`;}
function wizardView(error=''){const w=wizard;let body=`<div class="wizard-steps">${['Model & method','Data & identity','Training setup'].map((s,i)=>`<div class="wizard-step ${w.step===i+1?'active':''}"><b>${i+1}</b>${s}</div>`).join('')}</div>${error?`<div class="callout error">${icon('info')}${esc(error)}</div>`:''}`;if(w.step===1){body+=field('run-name','Run name',w.name)+`<div class="field"><label>Fine-tuning method</label><div class="method-options">${Object.entries(methods).map(([k,m])=>`<button class="method-option ${w.method===k?'selected':''}" data-action="select-method" data-method="${k}">${icon(m.icon)}<strong>${m.name}</strong><small>${m.foot}</small></button>`).join('')}</div></div>`+field('run-model','Base model',w.model,'text','placeholder="Local .gguf file, model folder or Hugging Face ID"',(/\.gguf$/i.test(w.model)?'Local GGUF import supports Llama-family models. We restore training weights on disk, train with your method, then export a new GGUF.':w.offline?'Offline mode: model files must already be on this machine.':'Missing model and tokenizer files will download from Hugging Face, then stay cached.'))+`<div class="toggle-row" style="padding-top:0;margin-bottom:20px"><div><strong>Download missing models</strong><p>Only model files are fetched. Your training data stays local.</p></div><input id="run-downloads" type="checkbox" class="toggle" aria-label="Download missing models for this run" ${!w.offline?'checked':''}></div><div class="callout" style="margin-bottom:0">${icon('leaf')}Have a GGUF? Enter its full local file path above. Import restores its weights on disk before training. Start with a compact model that fits your GPU.</div>`;}else if(w.step===2){body+=`<div class="field"><label for="run-dataset">Training dataset <button class="button ghost" data-action="wizard-import">${icon('plus')} Import new</button></label><select id="run-dataset"><option value="">Choose a dataset</option>${state.datasets.map(d=>`<option value="${d.id}" ${w.dataset_id===d.id?'selected':''}>${esc(d.name)} · ${fmt(d.rows)} examples</option>`).join('')}</select><small>Your data stays on this machine.</small></div>${w.method==='tuna'?`<div class="field"><label for="run-policy">Your model’s system policy ${pill('Tuna identity',true)}</label><textarea id="run-policy" rows="6">${esc(w.system_prompt)}</textarea><small>This prompt conditions every training example. Your dataset’s assistant replies teach the behavior, so make sure those replies follow your policy.</small></div><div class="callout warning" style="margin-bottom:0">${icon('shield')}The inference wrapper prevents callers replacing this prompt. Model behavior remains probabilistic; training is not an unbreakable instruction lock.</div>`:`<div class="callout" style="margin-bottom:0">${icon('data')}Existing system messages stay in your conversations. Training loss is applied to assistant responses.</div>`}`;}else{body+=`<div class="form-row">${field('epochs','Epochs',w.epochs,'number','min="0.01" max="1000" step="any"')}${field('learning_rate','Learning rate',w.learning_rate,'number','min="0.00000001" max="0.1" step="any"')}</div><div class="form-row">${field('batch_size','Micro batch size',w.batch_size,'number','min="1" max="128" step="1"')}${field('gradient_accumulation','Gradient accumulation',w.gradient_accumulation,'number','min="1" max="1024" step="1"')}</div><div class="form-row">${field('max_seq_length','Max sequence length',w.max_seq_length,'number','min="32" max="131072" step="1"')}${field('lora_rank','LoRA rank',w.lora_rank,'number','min="1" max="512" step="1"')}</div><div class="form-row">${field('lora_alpha','LoRA alpha',w.lora_alpha,'number','min="1" max="2048" step="1"')}${field('seed','Random seed',w.seed,'number','min="0" max="2147483647"')}</div><div class="toggle-row" style="padding-top:0"><div><strong>Gradient checkpointing</strong><p>Use less activation memory by recomputing during backpropagation.</p></div><input id="gradient_checkpointing" type="checkbox" class="toggle" aria-label="Gradient checkpointing" ${w.gradient_checkpointing?'checked':''}></div><div style="margin-top:18px" class="review-list"><div class="review-item"><span>Method</span><strong>${methods[w.method].name}</strong></div><div class="review-item"><span>Model access</span><strong>${w.offline?'Offline / local cache':'Downloads enabled'}</strong></div><div class="review-item"><span>Base model</span><strong>${esc(w.model.split(/[\\/]/).pop())}</strong></div><div class="review-item"><span>Dataset</span><strong>${esc(state.datasets.find(d=>d.id===w.dataset_id)?.name||'—')}</strong></div></div>${!state.status?.methods_ready?.[w.method]?`<div class="callout warning" style="margin-bottom:0">${icon('info')}<div>The training engine needs setup before this run can start. ${esc([...(state.status?.missing||[]),...(w.method!=='lora'?(state.status?.setup_actions||[]):[])].join(' · '))} You can save this configuration now.</div></div>`:''}`;}
openModal('New training run','Configure a local training run.',body,`${w.step>1?btn('Back','wizard-back','',''):btn('Cancel','close')}<div>${w.step===3?btn('Save config','save-config','','download'):''}${w.step<3?btn('Continue','wizard-next','primary','arrow'):btn('Start training','start-training','primary','play')}</div>`);}
function captureWizard(){const w=wizard;if(!w)return;if(w.step===1){w.name=document.querySelector('#run-name').value.trim();w.model=document.querySelector('#run-model').value.trim();w.offline=!document.querySelector('#run-downloads').checked;}if(w.step===2){w.dataset_id=document.querySelector('#run-dataset').value;const policy=document.querySelector('#run-policy');if(policy)w.system_prompt=policy.value.trim();}if(w.step===3){for(const k of ['epochs','learning_rate','batch_size','gradient_accumulation','max_seq_length','lora_rank','lora_alpha','seed']){const value=document.getElementById(k).value.trim();w[k]=value?Number(value):NaN;}w.gradient_checkpointing=document.querySelector('#gradient_checkpointing').checked;}}
function validateWizard(all=false){
 const w=wizard;if(!w)return 'Open a new training run to continue.';
 if(all||w.step===1){
  if(!w.name||!w.model)return 'Add a run name and a local model path or Hugging Face model ID.';
  if(w.name.length>160)return 'Run name must be at most 160 characters.';
  if(w.model.length>1000||w.model.includes('\0'))return 'Enter a valid model path or Hugging Face model ID (at most 1,000 characters).';
  if(/^https?:\/\//i.test(w.model))return 'Use the Hugging Face model ID (for example Qwen/Qwen3-0.6B), or a local file path.';
  if(!methods[w.method])return 'Choose Tuna, QLoRA, or LoRA.';
 }
 if(all||w.step===2){
  if(!w.dataset_id||!state.datasets.some(d=>d.id===w.dataset_id))return 'Choose or import a training dataset. The previous selection may have been removed.';
  if(w.method==='tuna'&&!w.system_prompt?.trim())return 'Write a system policy for your Tuna model.';
  if(typeof w.system_prompt!=='string'||w.system_prompt.length>50000)return 'The system policy must be text, at most 50,000 characters.';
 }
 if(all||w.step===3){
  for(const [key,label,min,max,integer] of [['epochs','Epochs',0.01,1000,false],['learning_rate','Learning rate',0.00000001,0.1,false],['batch_size','Micro batch size',1,128,true],['gradient_accumulation','Gradient accumulation',1,1024,true],['max_seq_length','Max sequence length',32,131072,true],['lora_rank','LoRA rank',1,512,true],['lora_alpha','LoRA alpha',1,2048,true],['seed','Random seed',0,2147483647,true]]){
   const n=w[key];if(typeof n!=='number'||!Number.isFinite(n)||n<min||n>max||(integer&&!Number.isInteger(n)))return `${label} must be ${integer?'a whole number':'a number'} between ${min} and ${max}.`;
  }
 }
 return '';
}
async function startTraining(){
 if(trainingPending||modalType!=='wizard')return;captureWizard();const error=validateWizard(true);if(error){wizardView(error);return;}
 const button=document.querySelector('[data-action=start-training]'),epoch=modalEpoch,owner=wizard;trainingPending=true;button.disabled=true;
 try{
  const {step,...config}=owner,result=await api('/runs',{method:'POST',body:JSON.stringify(config)}),id=(result.run||result).id;
  if(epoch===modalEpoch&&modalType==='wizard'&&wizard===owner){closeModal();navigate('runs');await refresh();await showRun(id);}else await refresh();
  toast('Training run created. Follow its progress in Training runs.');
 }catch(e){if(epoch===modalEpoch&&modalType==='wizard'&&wizard===owner)wizardView(e.message);else toast(e.message);}
 finally{trainingPending=false;if(button.isConnected)button.disabled=false;}
}
async function showDataset(id){const epoch=modalEpoch,request=++runRequest;modalLookup=request;try{const result=await api('/datasets/'+encodeURIComponent(id));if(epoch!==modalEpoch||request!==runRequest)return;const d=result.dataset||result;if(!isRecord(d)||typeof d.id!=='string')throw new Error('The dataset preview is unavailable. Refresh the dataset list and try again.');modalType='dataset';modalData=d;openModal(esc(d.name||'Dataset preview'),`${fmt(d.rows)} examples · ${bytes(d.size_bytes||0)} · stored locally`,`${(Array.isArray(d.preview)?d.preview:Array.isArray(d.examples)?d.examples:[]).slice(0,5).map((row,i)=>`<div class="field"><label>Example ${i+1}</label><div class="code">${esc(JSON.stringify(row,null,2))}</div></div>`).join('')||'<p class="muted">No preview available.</p>'}`,`${btn('Close','close')}<div>${btn('Use in a run','dataset-run','primary','plus')}</div>`);}catch(e){if(epoch===modalEpoch&&request===runRequest)toast(e.message);}finally{if(modalLookup===request)modalLookup=0;}}
function lossChart(metrics){const ms=metrics.filter(m=>typeof m.loss==='number'&&Number.isFinite(m.loss));if(ms.length<2)return '<div class="empty" style="padding:20px"><p>The loss curve appears after two training measurements.</p></div>';const vals=ms.map(m=>m.loss),max=Math.max(...vals),min=Math.min(...vals),range=max-min||1;const points=ms.map((m,i)=>`${40+i/(ms.length-1)*670},${15+(max-m.loss)/range*105}`).join(' ');return `<svg class="chart" viewBox="0 0 740 150" preserveAspectRatio="none" aria-label="Measured training loss chart"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#91bc91" stop-opacity=".2"/><stop offset="1" stop-color="#91bc91" stop-opacity="0"/></linearGradient></defs>${[15,67,120].map(y=>`<line x1="40" y1="${y}" x2="710" y2="${y}" stroke="#edf2eb"/>`).join('')}<polygon points="40,120 ${points} 710,120" fill="url(#chartFill)"/><polyline points="${points}" fill="none" stroke="#438b69" stroke-width="2"/><text x="0" y="18" class="chart-label">${max.toFixed(2)}</text><text x="0" y="123" class="chart-label">${min.toFixed(2)}</text><text x="40" y="145" class="chart-label">Step ${ms[0].step||1}</text><text x="665" y="145" class="chart-label">Step ${ms.at(-1).step||ms.length}</text></svg>`;}
function trainingProof(r){
 const v=r.summary?.adapter_verification,source=r.summary?.gguf_import;
 if(!v?.learned_updates_present)return '';
 return `<div class="callout" style="margin-bottom:20px">${icon('check')}<div><strong>Learned weight updates verified</strong><br><span class="small muted">${fmt(v.nonzero_lora_b_matrices)} / ${fmt(v.lora_b_matrices)} adapter matrices contain trained updates.${source?' Started from your local GGUF. Export merges these changes into a new standalone GGUF.':''}</span></div></div>`;
}
function ggufPanel(r){
 if(r.status!=='completed')return '';
 const g=r.gguf||{},active=['running','stopping'].includes(g.status),ready=g.status==='completed';
 return `<section class="gguf-panel"><div class="section-head"><div><h3>Save as GGUF</h3><p class="small muted">A standalone model with your trained adapter merged in.</p></div>${g.status?statusBadge(g.status):pill('Local export',true)}</div>
 ${active?`<div class="callout" style="margin-bottom:12px">${icon('refresh')}<div>${esc(g.message||'Preparing export…')}${g.total?`<br><span class="small muted">${fmt(g.completed||0)} / ${fmt(g.total)} weight matrices</span>`:''}</div></div>`:''}
 ${g.error?`<div class="callout error">${icon('info')}${esc(g.error)}</div><details class="small muted"><summary>Export log</summary><pre class="code">${esc((Array.isArray(g.logs)?g.logs:[]).slice(-12).join('\n'))}</pre></details>`:''}
 ${ready?`<div class="gguf-downloads"><a class="button primary" href="/api/runs/${encodeURIComponent(r.id)}/gguf" download>${icon('download')}Download GGUF</a><a class="button" href="/api/runs/${encodeURIComponent(r.id)}/gguf/companion" download>${icon('file')}Ollama files</a><span class="small muted">${esc(String(g.result?.format||g.format||'').toUpperCase())} · ${bytes(g.result?.size_bytes||0)}</span>${g.result?.architecture==='llama'?btn('Fine-tune this GGUF','train-gguf','','fish'):''}</div>`:''}
 <div class="gguf-options"><label class="small muted" for="gguf-format">Format</label><select id="gguf-format" ${active?'disabled':''}><option value="q8_0" ${g.format!=='f16'?'selected':''}>Q8_0 · 8-bit, smaller file</option><option value="f16" ${g.format==='f16'?'selected':''}>F16 · 16-bit precision</option></select>${active?btn(g.status==='stopping'?'Stopping…':'Stop export','stop-gguf','danger','stop'):btn(ready?'Export selected format':'Export GGUF','export-gguf','','download')}</div>
 ${r.config?.method==='tuna'||r.method==='tuna'?'<p class="small muted" style="font-size:10px;margin-top:10px">The Ollama files include your Tuna system prompt. GGUF alone does not enforce a system prompt.</p>':''}</section>`;
}
async function showRun(id,quiet=false){if(quiet&&(modalLookup||modalType!=='run'||activeRun!==id))return;const epoch=modalEpoch,request=++runRequest;if(!quiet){modalLookup=request;activeRun=id;}try{const result=await api('/runs/'+encodeURIComponent(id));if(epoch!==modalEpoch||request!==runRequest||(quiet&&(modalType!=='run'||activeRun!==id)))return;const r=normalizeRuns([result.run||result])[0];if(!r)throw new Error('This run is unavailable. Refresh the run list and try again.');const revision=value=>JSON.stringify([value?.status,value?.error,value?.metrics?.length,value?.metrics?.at(-1)?.step,value?.logs?.length,value?.logs?.at(-1)?.timestamp,value?.artifact_available,value?.gguf?.status,value?.gguf?.updated_at,value?.gguf?.stage]);if(quiet&&modalData?.id===r.id&&revision(modalData)===revision(r))return;const oldScroll=document.querySelector('.modal-body')?.scrollTop||0;activeRun=id;modalType='run';modalData=r;const m={...lastMetric(r),...r.summary},logs=Array.isArray(r.logs)?r.logs.map(logMessage).join('\n'):r.logs||'Waiting for the trainer…';openModal(esc(r.name||r.config?.name||'Training run'),`${methods[r.method||r.config?.method]?.name||'Training'} · ${esc(r.model||r.config?.model||'Local model')}`,`<div style="display:flex;justify-content:space-between;margin-bottom:20px">${statusBadge(r.status)}<span class="muted small">${esc(r.id)}</span></div>${r.error?`<div class="callout error">${icon('info')}${esc(r.error)}</div>`:''}<div class="metric-grid"><div class="metric"><span>Latest loss</span><strong>${latestLoss(r)}</strong></div><div class="metric"><span>Peak VRAM</span><strong>${metricNum(m.peak_vram_gb??m.peak_memory_gb??(typeof m.peak_vram_mb==='number'?m.peak_vram_mb/1024:undefined),' GB')}</strong></div><div class="metric"><span>Tokens / second</span><strong>${metricNum(m.tokens_per_second)}</strong></div><div class="metric"><span>Elapsed training</span><strong>${metricNum(m.elapsed_seconds??m.train_seconds,' s')}</strong></div></div><div class="chart-wrap"><h3>Training loss <span class="muted" style="font-weight:400">/ measured per step</span></h3>${lossChart(metricsOf(r))}</div>${trainingProof(r)}${ggufPanel(r)}<div class="section-head"><h3 style="font-size:11px">Local training log</h3><span class="small muted" style="font-size:9px">${['running','queued','starting','stopping'].includes(r.status)?'Updates automatically':'Saved on this machine'}</span></div><pre class="log">${esc(logs)}</pre>`,`${btn('Close','close')}<div>${r.status==='completed'?`<button class="button primary" data-action="chat-run" data-id="${esc(id)}">${icon('chat')}Chat with model</button><a class="button" href="/api/runs/${encodeURIComponent(id)}/export" download>${icon('download')}Export adapter</a>`:''}${['running','queued','starting'].includes(r.status)?btn('Stop run','stop-run','danger','stop'):''}${['failed','stopped'].includes(r.status)?btn('Retry run','retry-run','','refresh'):''}${btn('Export config','export-run','','download')}</div>`,true,!quiet);if(quiet){document.querySelector('.modal-body').scrollTop=oldScroll;}}catch(e){if(!quiet&&epoch===modalEpoch&&request===runRequest)toast(e.message);}finally{if(modalLookup===request)modalLookup=0;}}
function baselineModal(){modalType='baseline';openModal('Import benchmark baseline','Import a measured result from another training framework.',`<div id="baseline-error"></div><div class="field"><label for="baseline-content">Baseline JSON</label><textarea id="baseline-content" class="mono" rows="13" placeholder='${esc(JSON.stringify({framework:'Unsloth',model:'model-id',gpu:'GPU name',dataset:'dataset hash or revision',max_seq_length:1024,effective_batch_size:8,steps:100,peak_vram_gb:0,elapsed_seconds:0,tokens_per_second:0,loss:0},null,2))}'></textarea><small>Required: framework, model, gpu, dataset, steps, peak_vram_gb, elapsed_seconds, tokens_per_second, loss. Values must come from an actual measured run.</small></div>`,`${btn('Cancel','close')}<div>${btn('Save baseline','save-baseline','primary','check')}</div>`);}
function exportBenchmarks(){const results=state.runs.filter(r=>r.status==='completed').map(r=>({id:r.id,name:r.name||r.config?.name,source:'locally measured',config:r.config,metrics:r.metrics,summary:r.summary}));download('tuna-benchmarks.json',JSON.stringify({exported_at:new Date().toISOString(),device:state.status?.device,local_runs:results,external_baseline:state.baseline,comparison_note:'No performance superiority claim. Match all training conditions and assess quality.'},null,2));toast('Benchmark report exported.');}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action],[data-nav]');if(!target)return;if(target.dataset.nav){navigate(target.dataset.nav);return;}const action=target.dataset.action;if(target.disabled)return;const guarded=['sample','confirm-delete','stop-run','export-gguf','stop-gguf','refresh'].includes(action),key=action+':'+(target.dataset.id||activeRun||'');if(guarded&&pendingActions.has(key))return;if(guarded){pendingActions.add(key);target.disabled=true;}try{switch(action){case'menu':document.querySelector('.sidebar').classList.toggle('open');break;case'close':closeModal();break;case'new-run':case'custom-model':newRun();break;case'recipe':newRun(target.dataset.method);break;case'choose-model':newRun('qlora',models[+target.dataset.index].id);break;case'import':importModal();break;case'paste-sample':document.querySelector('#dataset-content').value=sampleContent();document.querySelector('#dataset-name').value='Friendly assistant · sample';break;case'sample':await api('/datasets',{method:'POST',body:JSON.stringify({name:'Friendly assistant · sample',content:sampleContent()})});await refresh();toast('Four sample conversations added. Use your own dataset for meaningful training.');break;case'save-dataset':await saveDataset();break;case'dataset':await showDataset(target.dataset.id);break;case'dataset-run':{const id=modalData.id;newRun();wizard.dataset_id=id;break;}case'delete-dataset':{const d=state.datasets.find(d=>d.id===target.dataset.id);if(!d){toast('This dataset is no longer available. Refresh the list.');break;}modalType='confirm-delete';modalData=d;openModal('Remove this dataset?',esc(d.name),'<p class="small muted">This removes its local training examples. Existing run artifacts are kept.</p>',`${btn('Keep dataset','close')}<div>${btn('Delete dataset','confirm-delete','danger','trash')}</div>`);break;}case'confirm-delete':{const id=modalData?.id,epoch=modalEpoch;if(!id)break;await api('/datasets/'+encodeURIComponent(id),{method:'DELETE'});if(epoch===modalEpoch)closeModal();await refresh();toast('Dataset removed.');break;}case'select-method':captureWizard();wizard.method=target.dataset.method;wizardView();break;case'wizard-next':{captureWizard();const error=validateWizard();if(error){wizardView(error);return;}wizard.step++;wizardView();break;}case'wizard-back':captureWizard();wizard.step--;wizardView();break;case'wizard-import':captureWizard();importModal(true);break;case'save-config':{captureWizard();const error=validateWizard(true);if(error){wizardView(error);break;}const{step,...config}=wizard;download('tuna-training-config.json',JSON.stringify(config,null,2));toast('Training configuration exported.');break;}case'start-training':await startTraining();break;case'run':await showRun(target.dataset.id);break;case'stop-run':{const id=activeRun,epoch=modalEpoch;await api('/runs/'+encodeURIComponent(id)+'/stop',{method:'POST',body:'{}'});toast('Stop requested.');if(epoch===modalEpoch)await showRun(id);break;}case'retry-run':{const config=modalData.config;newRun(config.method,config.model);wizard={...wizard,...config,step:1,offline:typeof config.offline==='boolean'?config.offline:!!state.settings.offline};wizardView();break;}case'train-gguf':{const r=modalData;const path=state.status.data_directory+'/runs/'+r.id+'/gguf/'+r.gguf.result.filename;newRun(r.method==='tuna'?'tuna':'qlora',path);for(const key of ['dataset_id','system_prompt','epochs','learning_rate','batch_size','gradient_accumulation','max_seq_length','lora_rank','lora_alpha','gradient_checkpointing','seed'])if(r.config[key]!==undefined)wizard[key]=r.config[key];wizard.name=r.name+' · GGUF tune';wizard.offline=true;wizardView();break;}case'export-gguf':{const id=activeRun,epoch=modalEpoch;target.disabled=true;try{await api('/runs/'+encodeURIComponent(id)+'/gguf',{method:'POST',body:JSON.stringify({format:document.querySelector('#gguf-format').value})});if(epoch===modalEpoch)await showRun(id);toast('GGUF export started. You can follow progress here.');}finally{if(target.isConnected)target.disabled=false;}break;}case'stop-gguf':{const id=activeRun,epoch=modalEpoch;await api('/runs/'+encodeURIComponent(id)+'/gguf/stop',{method:'POST',body:'{}'});if(epoch===modalEpoch)await showRun(id);break;}case'export-run':download('tuna-run-config.json',JSON.stringify(modalData.config||modalData,null,2));break;case'filter':state.filter=target.dataset.value;render();break;case'refresh':await refresh();toast(state.connected?'Engine status refreshed.':'The local engine is unavailable. Check its terminal and try again.');break;case'download-sample':download('tuna-example.jsonl',sampleContent(),'application/x-ndjson');break;case'export-benchmarks':exportBenchmarks();break;case'baseline':baselineModal();break;case'save-baseline':{try{const b=JSON.parse(document.querySelector('#baseline-content').value);if(!isRecord(b))throw new Error('Paste a JSON object containing measured benchmark results.');for(const k of ['framework','model','gpu','dataset'])if(typeof b[k]!=='string'||!b[k].trim())throw new Error(`Add a non-empty ${k}.`);for(const k of ['steps','peak_vram_gb','elapsed_seconds','tokens_per_second','loss'])if(typeof b[k]!=='number'||!Number.isFinite(b[k])||b[k]<0)throw new Error(`${k} must be a non-negative number.`);if(b.steps<=0||b.elapsed_seconds<=0)throw new Error('Measured steps and elapsed time must be greater than zero.');state.baseline={...b,source:'User-supplied, not independently verified',imported_at:new Date().toISOString()};saveStored('tuna-baseline',state.baseline);closeModal();render();toast('External baseline saved.');}catch(err){document.querySelector('#baseline-error').innerHTML=`<div class="callout error">${esc(err.message)}</div>`;}break;}}}catch(err){toast(err.message);}finally{if(guarded){pendingActions.delete(key);if(target.isConnected)target.disabled=false;}}});
document.addEventListener('change',async e=>{
 if(e.target.id==='dataset-file')loadFile(e.target.files[0]);
 if(e.target.id==='model-download-toggle'){
  if(settingsPending){e.target.checked=!state.settings.offline;return;}
  const offline=!e.target.checked,control=e.target;settingsPending=true;control.disabled=true;
  try{const result=await api('/settings',{method:'PUT',body:JSON.stringify({offline})});state.settings.offline=typeof result.settings?.offline==='boolean'?result.settings.offline:offline;saveStored('tuna-settings',state.settings);toast(state.settings.offline?'Offline mode enabled. Cached models only.':'Model downloads enabled. Datasets stay local.');}
  catch(error){control.checked=!state.settings.offline;toast(error.message);}
  finally{settingsPending=false;if(control.isConnected)control.disabled=false;}
 }
});
document.addEventListener('input',e=>{if(e.target.id==='run-search'){const start=e.target.selectionStart;state.search=e.target.value;render();const input=document.querySelector('#run-search');input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalType)closeModal();if(e.key==='Enter'&&e.target.matches('tr[data-action]'))e.target.click();if(e.key==='Tab'&&modalType){const items=[...document.querySelectorAll('.modal button:not(:disabled),.modal a[href],.modal input:not(:disabled),.modal select,.modal textarea')].filter(el=>el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('#drop-zone');if(zone){e.preventDefault();zone.classList.add('drag');}});
document.addEventListener('dragleave',e=>{e.target.closest('#drop-zone')?.classList.remove('drag');});
document.addEventListener('drop',e=>{const zone=e.target.closest('#drop-zone');if(zone){e.preventDefault();zone.classList.remove('drag');loadFile(e.dataTransfer.files[0]);}});
window.addEventListener('DOMContentLoaded',()=>{render();refresh(true);setInterval(()=>{if(!document.hidden)refresh();},4000);});

document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
